        for c in range(cols):
            val = grid[r][c]
            if val != 0:
                color_count[val] = color_count.get(val, 0) + 1

    # Identify source color - the one with LOWER count than others (minority color)
    # In demo 1: 4 was source (count < 9 which was background)
