    max_count = max(color_count.values())

    sources = set()
    for color, count in color_count.items():
        if count != max_count:
            sources.add(color)

    if not sources:
        return [row[:] for row in grid]

    source_color = list(sources)[0]

    # Find all source pixels
    source_pixels = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == source_color:
                source_pixels.append((r, c))

    new_grid = [row[:] for row in grid]

    # 8-way flood fill: replace reachable 0s with source color
    queue = deque(source_pixels)

    while queue:
        r, c = queue.popleft()

        # Check all 8 neighbors
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    # Only fill 0s, not other colors
                    if new_grid[nr][nc] == 0:
                        new_grid[nr][nc] = source_color
                        queue.append((nr, nc))
                    # Don't skip source_color neighbors - they're already in queue via initial list

    return new_grid
